script:
frappe.ui.form.on("Sales Invoice", {
    refresh(frm) {
        setup_add_row_guard(frm);
    },

    validate(frm) {
        validate_all_qty(frm);
    }
});


frappe.ui.form.on("Sales Invoice Item", {
    item_code(frm, cdt, cdn) {
        const row = locals[cdt][cdn];

        if (!row.item_code) {
            return;
        }

        // ERPNext normally sets Qty = 1 after item selection.
        // Reset it after standard item processing.
        setTimeout(() => {
            if (cint(frm.doc.is_return) === 1) {
                if (flt(row.qty) > 0) {
                    frappe.model.set_value(cdt, cdn, "qty", 0);
                }
            } else {
                frappe.model.set_value(cdt, cdn, "qty", 0);
            }
        }, 500);
    }
});


function get_invalid_qty_row(frm) {
    const is_return = cint(frm.doc.is_return) === 1;

    return (frm.doc.items || []).find(row => {
        if (!row.item_code) return false;
        if (is_return) {
            return flt(row.qty) >= 0;
        }
        return flt(row.qty) < 1;
    });
}


function validate_all_qty(frm) {
    const is_return = cint(frm.doc.is_return) === 1;

    const invalid_rows = (frm.doc.items || []).filter(row => {
        if (!row.item_code) return false;
        if (is_return) {
            return flt(row.qty) >= 0;
        }
        return flt(row.qty) < 1;
    });

    if (!invalid_rows.length) {
        return;
    }

    const rows = invalid_rows.map(row => row.idx).join(", ");

    if (is_return) {
        frappe.throw(
            __(
                "Quantity must be negative (less than 0) for Item Row(s): {0}",
                [rows]
            )
        );
    } else {
        frappe.throw(
            __(
                "Quantity must be 1 or more for Item Row(s): {0}",
                [rows]
            )
        );
    }
}


function setup_add_row_guard(frm) {
    const grid = frm.fields_dict.items.grid;

    if (!grid || !grid.wrapper || !grid.wrapper[0]) {
        return;
    }

    const wrapper = grid.wrapper[0];

    // Remove previous listener if refresh runs again
    if (wrapper._qty_add_row_guard) {
        wrapper.removeEventListener(
            "click",
            wrapper._qty_add_row_guard,
            true
        );
    }

    const handler = function (event) {

        const add_row_button = event.target.closest(
            ".grid-add-row, .grid-add-multiple-rows"
        );

        if (!add_row_button) {
            return;
        }

        const invalid_row = get_invalid_qty_row(frm);

        if (!invalid_row) {
            return;
        }

        // Stop Frappe before it creates another row
        event.preventDefault();
        event.stopPropagation();
        event.stopImmediatePropagation();

        const is_return = cint(frm.doc.is_return) === 1;

        frappe.msgprint({
            title: __("Invalid Quantity"),
            indicator: "red",
            message: is_return
                ? __(
                    "Set quantity to a negative value (less than 0) in Row {0} before adding another item.",
                    [invalid_row.idx]
                )
                : __(
                    "Set quantity to 1 or more in Row {0} before adding another item.",
                    [invalid_row.idx]
                )
        });

        return false;
    };

    wrapper._qty_add_row_guard = handler;

    // IMPORTANT: true = capture phase
    wrapper.addEventListener(
        "click",
        handler,
        true
    );
}
